y-picker-browse\": \"node ./scripts/smoke-directory-picker-browse.mjs\",\n    \"capture:screenshots\": \"node ./scripts/capture-mobile-screenshots.mjs\",\n    \"check:release-tag\": \"node ./scripts/check-release-version.mjs --tag-env\",\n    \"check:android-release-tag\": \"node ./scripts/check-release-version.mjs --android-tag-env\",\n    \"check:version\": \"node ./scripts/check-release-version.mjs\",\n    \"check:companion-package\": \"node ./scripts/check-companion-package.mjs\",\n    \"check:attribution\": \"node ./scripts/check-attribution.mjs\",\n    \"check:docs\": \"node ./scripts/check-docs.mjs\",\n    \"clean\": \"node ./scripts/clean.mjs\",\n    \"generate:funnel-licenses\": \"node ./scripts/funnel-third-party-licenses.mjs --write\",\n    \"lint\": \"tsc --noEmit\",\n    \"test\": \"vitest run --pool=threads --maxWorkers=1\",\n    \"test:watch\": \"vitest\",\n    \"typecheck\": \"tsc --noEmit\",\n    \"prepack\": \"npm run check:version && npm run check:docs && npm run check:funnel-licenses && npm run build\",\n    \"verify\": \"npm run check:version && npm run check:docs && npm run check:companion-package && npm run check:funnel-licenses && npm run check:mobile-release && npm run typecheck && npm run test && npm run build && npm pack --dry-run\"\n  },\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/saya-ch/dsh-mobile.git\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/saya-ch/dsh-mobile/issues\"\n  },\n  \"homepage\": \"https://github.com/saya-ch/dsh-mobile#readme\",\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"dsh\",\n    \"dsh-plugin\",\n    \"plugin\",\n    \"android\",\n    \"lan\",\n    \"remote-access\",\n    \"tailscale\",\n    \"cpolar\",\n    \"frp\",\n    \"self-hosted\",\n    \"reverse-proxy\",\n    \"mobile\",\n    \"https\"\n  ],\n  \"license\": \"Apache-2.0\",\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh-client-connection\": \"*\",\n    \"@deepseek-ai/dsh-commands\": \"*\",\n    \"@deepseek-ai/dsh-host-webserver\": \"*\",\n    \"@deepseek-ai/dsh-llm\": \"*\",\n    \"react\": \"^18.2.0\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/cordis\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-connection\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-commands\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-host-webserver\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-llm\": {\n      \"optional\": true\n    },\n    \"react\": {\n      \"optional\": true\n    }\n  },\n  \"dependencies\": {\n    \"@deepseek-ai/schemastery\": \"^3.18.1\",\n    \"@noble/hashes\": \"1.8.0\",\n    \"bonjour-service\": \"1.4.4\",\n    \"eventsource-parser\": \"3.1.0\",\n    \"qrcode\": \"^1.5.4\",\n    \"selfsigned\": \"^5.5.0\",\n    \"ws\": \"8.22.0\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.0.4\",\n    \"@deepseek-ai/cordis-plugin-include\": \"1.0.9\",\n    \"@deepseek-ai/cordis-plugin-loader\": \"1.0.5\",\n    \"@deepseek-ai/dsh-agent\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-attachment\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-brand\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-client-connection\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-commands\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-host-webserver\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-invariants\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-llm\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-scope\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-session\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-timeout\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-typert-protocol\": \"0.1.7-rc.2\",\n    \"@types/js-yaml\": \"^4.0.9\",\n    \"@types/node\": \"^26.5.1\",\n    \"@types/qrcode\": \"^1.5.5\",\n    \"@types/react\": \"~18.3.1\",\n    \"@types/ws\": \"8.18.2\",\n    \"core-js\": \"^3.50.0\",\n    \"js-yaml\": \"^4.3.2\",\n    \"playwright\": \"1.63.0\",\n    \"react\": \"^18.2.0\",\n    \"tsdown\": \"^0.23.0\",\n    \"typescript\": \"^7.0.2\",\n    \"vitest\": \"^5.0.2\"\n  },\n  \"directories\": {\n    \"lib\": \"lib\",\n    \"test\": \"tests\"\n  },\n  \"author\": \"\"\n}\n"
